PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE movement (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE exercise (
  id TEXT PRIMARY KEY,
  name TEXT,
  archived INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE exercise_part (
  exercise_id TEXT NOT NULL REFERENCES exercise(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  movement_id TEXT NOT NULL REFERENCES movement(id),
  reps INTEGER NOT NULL DEFAULT 1 CHECK (reps >= 1),
  PRIMARY KEY (exercise_id, position)
);
CREATE TABLE scheme (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  kind TEXT NOT NULL CHECK (kind IN ('max', 'fixed', 'free')),
  sets INTEGER,
  reps INTEGER,
  position INTEGER NOT NULL DEFAULT 0
, hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE log_entry (
  id TEXT PRIMARY KEY,
  exercise_id TEXT NOT NULL REFERENCES exercise(id),
  scheme_id TEXT NOT NULL REFERENCES scheme(id),
  date TEXT NOT NULL,
  notes TEXT,
  source TEXT NOT NULL DEFAULT 'app' CHECK (source IN ('app', 'jefit')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE log_set (
  id TEXT PRIMARY KEY,
  log_entry_id TEXT NOT NULL REFERENCES log_entry(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  reps INTEGER NOT NULL CHECK (reps >= 1),
  weight_kg REAL NOT NULL CHECK (weight_kg >= 0),
  success INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE benchmark (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  category TEXT NOT NULL,
  protocol TEXT,
  archived INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE benchmark_measure (
  id TEXT PRIMARY KEY,
  benchmark_id TEXT NOT NULL REFERENCES benchmark(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  name TEXT NOT NULL,
  unit TEXT NOT NULL CHECK (unit IN ('time', 'rounds_reps', 'reps', 'cal', 'cm', 'deg', 'kg', 'm')),
  better TEXT NOT NULL CHECK (better IN ('higher', 'lower'))
);
CREATE TABLE benchmark_result (
  id TEXT PRIMARY KEY,
  benchmark_id TEXT NOT NULL REFERENCES benchmark(id) ON DELETE CASCADE,
  date TEXT NOT NULL,
  variant TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE benchmark_value (
  result_id TEXT NOT NULL REFERENCES benchmark_result(id) ON DELETE CASCADE,
  measure_id TEXT NOT NULL REFERENCES benchmark_measure(id),
  value REAL NOT NULL CHECK (value >= 0),
  PRIMARY KEY (result_id, measure_id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX exercise_part_movement ON exercise_part(movement_id);
CREATE INDEX log_entry_exercise_date ON log_entry(exercise_id, date);
CREATE INDEX log_entry_scheme ON log_entry(scheme_id);
CREATE INDEX log_set_entry ON log_set(log_entry_id);
CREATE INDEX benchmark_measure_benchmark ON benchmark_measure(benchmark_id, position);
CREATE INDEX benchmark_result_benchmark_date ON benchmark_result(benchmark_id, date);
CREATE INDEX benchmark_value_measure ON benchmark_value(measure_id);
